// Custom Worker entry: OpenNext handles HTTP; we add the Queue consumer and the
// ReadingRoom Durable Object. `.open-next/worker.js` is generated by
// `opennextjs-cloudflare build`, so run that before `wrangler dev/deploy`.
import openNext from "./.open-next/worker.js";
import { handleQueue } from "./src/lib/cf/consumer.js";

export { ReadingRoom } from "./src/lib/cf/reading-room.js";

export default {
  fetch: (request, env, ctx) => openNext.fetch(request, env, ctx),
  queue: (batch, env) => handleQueue(batch, env),
};
